 const auto refs=fs::path(NANO_TEST_SOURCE)/"tests/fixtures/consensus-slashing-official";const auto reference=load(refs/"manifest.json");for(const auto& [name,info]:reference.at("referenceFiles").items())check(hex(sha256(binary(refs/name))).substr(2)==info.at("sha256").get<std::string>(),"config digest");
 const auto preset=read(refs/"minimal-phase0.yaml");auto p=[&](const char* key){return parameter(preset,key);};
