  const auto pre=binary(root/name/"pre.ssz"),post=binary(root/name/"post.ssz");const auto state=ffg_state(pre),original=state;const auto registry=decode(pre),old_registry=registry;const auto randao=ffg_randao(pre),old_randao=randao;
