   auto s=state;s.checkpoints.justification_bits=16;refuse(s,registry,randao,rules);s=state;s.checkpoints.finalized.epoch=registry.epoch+1;refuse(s,registry,randao,rules);s=state;s.block_roots.resize(1);refuse(s,registry,randao,rules);
