   auto reg=registry;reg.epoch+=1;refuse(state,reg,randao,rules);reg=registry;reg.validators.erase(1);refuse(state,reg,randao,rules);reg=registry;reg.validators.at(0).effective_balance=rules.maximum_effective_balance+1;refuse(state,reg,randao,rules);
   auto r=randao;r.epoch+=1;refuse(state,registry,r,rules);r=randao;r.mixes.resize(2);refuse(state,registry,r,rules);
